#!/usr/bin/env node
// Downloads the public OGame API files of every universe in the 2026 merges (merges.mjs) and writes data/,
// which index.html reads. Run it by hand whenever you want fresh rankings:
//
//   node fetch.mjs
//
// Only the official public API (https://s<N>-<community>.ogame.gameforge.com/api/...) is used: no login, no
// game page, no private data. The highscore files are regenerated by Gameforge about once an hour and
// players/alliances once a day, so there is no point running this more often than that. Each universe is its
// own server (s<N>-<community>), and each server gets one request at a time with a pause between them; a few
// universes download side by side (WORKERS), so the whole run fits the build time limits (Netlify stops a
// build at 18 minutes, one universe after the other takes about 25). Nothing here runs on a timer
// (AGENTS.md 1.3, 6).
//
// data/ holds scripts (window.EXODUS_INDEX = ..., then one file per universe) rather than .json files so that
// index.html also works when opened straight from disk: browsers refuse fetch() on file:// pages. With about
// 330 universes one file would weigh tens of megabytes, so the page loads only the universes of the ranking
// on screen.

import { mkdirSync, rmSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { MERGES } from './merges.mjs';

// highscore.xml?category=1 (players), by type
// Type 8 is the overall lifeform ranking. The API schema stops at type 1, so this was checked on the data:
// on s195, for 1987 of 1988 players type 8 equals types 9 + 10 + 11 to within 2 points of rounding, so 8 is the
// total of those three lifeform sub-rankings. What 9, 10 and 11 each are was not verified; they are not used.
const CATEGORIES = [ { type:0, key:'total' }, { type:1, key:'economy' }, { type:2, key:'research' }, { type:3, key:'military' }, { type:8, key:'lifeform' } ];

const PAUSE_MS = 400;
const WORKERS = 6;

const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

const get = async url =>
{
    for(let attempt = 1; ; attempt++)
    {
        try
        {
            const response = await fetch(url, { headers:{ 'User-Agent':'ogame-exodus merged rankings' } });
            if(!response.ok) throw new Error(`HTTP ${response.status}`);
            return await response.text();
        }
        catch(error)
        {
            if(attempt >= 3) throw new Error(`${url}: ${error.message}`);
            await sleep(2000 * attempt);
        }
        finally
        {
            await sleep(PAUSE_MS);
        }
    }
};

// The API files are flat lists of self-closing tags; their attributes are all that is needed.
const decode = text => text.replace(/&quot;/g, '"').replace(/&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const tags = (xml, name) => Array.from(xml.matchAll(new RegExp(`<${name}\\s([^>]*?)/?>`, 'g')), match =>
{
    const attributes = {};
    for(const [, key, value] of match[1].matchAll(/([\w-]+)="([^"]*)"/g)) attributes[key] = decode(value);
    return attributes;
});
const rootAttribute = (xml, attribute) => (xml.match(new RegExp(`${attribute}="(\\d+)"`)) || [])[1];

const fetchUniverse = async (community, number) =>
{
    const base = `https://s${number}-${community.toLowerCase()}.ogame.gameforge.com/api`;
    const server = await get(`${base}/serverData.xml`);
    const name = decode((server.match(/<name>([^<]*)<\/name>/) || [])[1] || ''); // the old Universe 1 has none: the page names it by number

    const players = new Map(tags(await get(`${base}/players.xml`), 'player').map(p => [p.id, p]));
    const alliances = new Map(tags(await get(`${base}/alliances.xml`), 'alliance').map(a => [a.id, a]));

    const rows = new Map();
    let updated = 0;

    for(const { type, key } of CATEGORIES)
    {
        const xml = await get(`${base}/highscore.xml?category=1&type=${type}`);
        updated = Math.max(updated, Number(rootAttribute(xml, 'timestamp')) || 0);

        for(const entry of tags(xml, 'player'))
        {
            const player = players.get(entry.id);
            if(player && /a/.test(player.status || '')) continue; // game administrators

            if(!rows.has(entry.id))
            {
                rows.set(entry.id,
                {
                    id:Number(entry.id),
                    name:player?.name || `#${entry.id}`,
                    status:player?.status || '',
                    alliance:alliances.get(player?.alliance)?.tag || '',
                });
            }

            const row = rows.get(entry.id);
            row[key] = [Number(entry.score) || 0, Number(entry.position) || 0];
            if(type === 3) row.ships = Number(entry.ships) || 0;
        }
    }

    // compact rows: [id, name, status, alliance, total, totalPos, economy, economyPos, research, researchPos, military, militaryPos, ships, lifeform, lifeformPos]
    const compact = Array.from(rows.values(), r => [r.id, r.name, r.status, r.alliance,
        ...(r.total || [0, 0]), ...(r.economy || [0, 0]), ...(r.research || [0, 0]), ...(r.military || [0, 0]), r.ships || 0, ...(r.lifeform || [0, 0])]);

    return { name, updated, players:compact };
};

// The merge map as index.html uses it. Universes are keyed 'IT 264' (the same number exists in several
// communities); a group gets a colour and its key (blue, orange...: index.html names it in each language), the same
// order in every community.
const COLORS = [ ['blue', '#5aa9f0'], ['orange', '#efa33c'], ['green', '#4fc97e'], ['purple', '#b48cff'], ['pink', '#f07ab4'] ];
const destination = text =>
{
    const [, plus, name, server] = text.match(/^(\+?)(.*?) ?\(([A-Z]{2} \d+)\)$/);
    return { server, name, existing:plus === '+' };
};

const communities = {};
const destinations = {};
const wanted = new Set();
for(const [community, groups] of Object.entries(MERGES))
{
    communities[community] = groups.map((group, index) =>
    {
        const universes = group.from.map(u => typeof u === 'number' ? `${community} ${u}` : u);
        const to = group.to.map(destination);
        universes.forEach(u => wanted.add(u));
        for(const d of to)
        {
            destinations[d.server] = { name:d.name, existing:d.existing };
            if(d.existing) wanted.add(d.server);
        }
        return { id:`${community}-${index + 1}`, name:COLORS[index][0], color:COLORS[index][1], universes, destinations:to.map(d => d.server), note:group.note || '' };
    });
}

// Each universe is fetched once even when several groups name it. One that fails (closed, unreachable) is
// left out and reported rather than stopping the whole run.
const dir = join(dirname(fileURLToPath(import.meta.url)), 'data');
rmSync(dir, { recursive:true, force:true });
mkdirSync(dir, { recursive:true });

const found = {};
const missing = [];
let total = 0;
const queue = [...wanted].sort();
const worker = async () =>
{
    for(let key; (key = queue.shift()); )
    {
        const [community, number] = key.split(' ');
        const server = `s${number}-${community.toLowerCase()}`;
        try
        {
            const { name, updated, players } = await fetchUniverse(community, Number(number));
            const file = `${community.toLowerCase()}-${number}.js`;
            writeFileSync(join(dir, file), `(window.EXODUS_U = window.EXODUS_U || {})[${JSON.stringify(key)}] = ${JSON.stringify(players)};\n`);
            found[key] = { name, updated, players:players.length, file };
            total += players.length;
            console.log(`${server} ... ${name}: ${players.length} players`);
        }
        catch(error)
        {
            missing.push(key);
            console.log(`${server} ... FAILED (${error.message})`);
            if(process.env.GITHUB_ACTIONS) console.log(`::warning::${key} left out: ${error.message}`);
        }
    }
};
await Promise.all(Array.from({ length:WORKERS }, worker));

// in key order, whatever order the workers finished in
const universes = Object.fromEntries(Object.keys(found).sort().map(key => [key, found[key]]));
missing.sort();

if(!Object.keys(universes).length) throw new Error('No universe could be downloaded');

const data = { generatedAt:Date.now(), communities, destinations, universes, missing };
writeFileSync(join(dir, 'index.js'), '// Generated by fetch.mjs - do not edit.\nwindow.EXODUS_INDEX = ' + JSON.stringify(data) + ';\n');

console.log(`\n${Object.keys(universes).length} universes, ${total} players, ${missing.length} missing -> ${dir}`);
